def hashes(commit):
 entries={}
 for rec in subprocess.check_output(['git','ls-tree','-r','-z',commit,'--','backend'],cwd=I).split(b'\0'):
  if rec:
   meta,name=rec.split(b'\t',1);mode,kind,oid=meta.split();assert kind==b'blob';entries[name.decode()]=oid.decode()
 objects=sorted(set(entries.values()));raw=subprocess.check_output(['git','cat-file','--batch'],cwd=I,input=('\n'.join(objects)+'\n').encode());pos=0;digests={}
 for oid in objects:
  end=raw.index(b'\n',pos);header=raw[pos:end].split();assert header[0].decode()==oid and header[1]==b'blob';size=int(header[2]);pos=end+1;digests[oid]=H(raw[pos:pos+size]);pos+=size;assert raw[pos:pos+1]==b'\n';pos+=1
 assert pos==len(raw);return {p:digests[o]for p,o in entries.items()}
